mapper.update:
UPDATE
CMWA_PRODUCT_DEPARTMENT SET D_NAME=#{sp.dName} WHERE
ID=#{sp.id,jdbcType=VARCHAR}

mapper.select:
SELECT PRO.NAME, PRO.FUNDID AS funcode, PRO.TYPEID, PRO.GROUPID, PD.ID AS id, PD.D_NAME AS DNAME, PRO.TERM, PRO.PAYMENTINTER, PRO.TERMUNIT, PRO.TERMINDAY as theTerm, PRO.ISHOT, PRO.DISORDER, PRO.PREFIX, PRO.OFFLINELIMIT, PRO.ONLINELIMIT, PRO.SCALE, PRO.MONEY, PRO.OFFLINEFUND, (CASE WHEN PRO.PROFIT IS NULL THEN '' ELSE TO_CHAR(PRO.PROFIT * 100) END) AS PROFIT, PRO.STATE AS states, PRO.CREATED_BY, PRO.REVIEW_STATUS, PRO.ADNAME, PRO.TEMPLETID, TE.TEMPLET_NAME AS TEMPLETNAME, PRO.ADTEXT, PRO.FUNDRISKLEVEL, HIGHRISKEXPLAIN, VENDCHANNELS, PRO.MSGDATE, (CASE WHEN PRO.APPOINTDATE IS NULL THEN '' ELSE TO_CHAR(TO_DATE(PRO.APPOINTDATE, 'YYYYMMDD'), 'YYYY-MM-DD') END) AS APPOINTDATE, PRO.DISPLAYLIMIT, (case when PRO.remainamt > 0 then PRO.Remainamt else 0 end) remainamt, PRO.MONEYSTEP, (CASE WHEN PRO.SUBDEADLINE IS NULL THEN '' ELSE TO_CHAR(TO_DATE(PRO.SUBDEADLINE, 'YYYYMMDD'), 'YYYY-MM-DD') END) AS SUBDEADLINE, (CASE WHEN PRO.INTERESTDATE IS NULL THEN '' ELSE TO_CHAR(TO_DATE(PRO.INTERESTDATE, 'YYYYMMDD'), 'YYYY-MM-DD') END) AS INTERESTDATE, (CASE WHEN PRO.SALESDATE IS NULL THEN '' ELSE TO_CHAR(TO_DATE(PRO.SALESDATE, 'YYYYMMDD'), 'YYYY-MM-DD') END) AS SALESDATE, (CASE WHEN PRO.MATURITYDATE IS NULL THEN '' ELSE TO_CHAR(TO_DATE(PRO.MATURITYDATE, 'YYYYMMDD'), 'YYYY-MM-DD') END) AS MATURITYDATE, IBF_GET_LASTNWORKDAY2(PRO.SALESDATE, 1, '') AS APPOINTENDDATE, IBF_GET_CURRENT_WORKDATE('') AS currentWorkdate, (SELECT T.TITLE FROM CMWA_FUNDELEMENT T WHERE T.FUNDID = PRO.FUNDID AND T.PERIOD=PRO.PERIOD AND T.SORTNO = '1' AND T.ELETYPE = '220' AND T.STATUS = 'Y') AS TEXTTITLE1, (SELECT T.TITLE FROM CMWA_FUNDELEMENT T WHERE T.FUNDID = PRO.FUNDID AND T.PERIOD=PRO.PERIOD AND T.SORTNO = '2' AND T.ELETYPE = '220' AND T.STATUS = 'Y') AS TEXTTITLE2, (SELECT T.TITLE FROM CMWA_FUNDELEMENT T WHERE T.FUNDID = PRO.FUNDID AND T.PERIOD=PRO.PERIOD AND T.SORTNO = '3' AND T.ELETYPE = '220' AND T.STATUS = 'Y') AS TEXTTITLE3, (SELECT T.CONTENT FROM CMWA_FUNDELEMENT T WHERE T.FUNDID = PRO.FUNDID AND T.PERIOD=PRO.PERIOD AND T.SORTNO = '1' AND T.ELETYPE = '220' AND T.STATUS = 'Y') AS TEXTCONTENT1, (SELECT T.CONTENT FROM CMWA_FUNDELEMENT T WHERE T.FUNDID = PRO.FUNDID AND T.PERIOD=PRO.PERIOD AND T.SORTNO = '2' AND T.ELETYPE = '220' AND T.STATUS = 'Y') AS TEXTCONTENT2, (SELECT T.CONTENT FROM CMWA_FUNDELEMENT T WHERE T.FUNDID = PRO.FUNDID AND T.PERIOD=PRO.PERIOD AND T.SORTNO = '3' AND T.ELETYPE = '220' AND T.STATUS = 'Y') AS TEXTCONTENT3, PRO.PERIOD FROM CMWA_FUND_REVIEW PRO, CMWA_PRODUCT_DEPARTMENT PD, CONTRACT_TEMPLETS TE WHERE PRO.GROUPID = PD.ID(+) AND PRO.TEMPLETID = TE.TEMPLET_ID(+) AND LENGTH(PRO.FUNDID) = '6'
AND PRO.FUNDID =#{sp.fundid}
AND PRO.ADNAME LIKE CONCAT(CONCAT('%', #{sp.dname}),'%')
AND PRO.FUNDID LIKE CONCAT(CONCAT('%',#{sp.funcode}),'%')
AND PRO.PERIOD = #{sp.period, jdbcType = NUMERIC}
order by PRO.INSERTTIMESTAMP desc

SELECT W_ID,ID,W_WENTI,W_DAAN,FUNCODE FROM CMWA_WENTI WHERE 1=1

	AND FUNCODE = #{sp.funcode}


	AND FUNCODE = #{sp.fundid}


	and period = #{sp.period}

ORDER BY ID ASC

mapper.delete:
DELETE FROM CMWA_WENTI
WHERE FUNCODE = #{funcode}

	and period = #{period}

DELETE FROM
cmwa_fundelement WHERE FUNDID=#{funcode} 
AND ELETYPE in('220','110','120','240','230') AND STATUS='Y'

	AND PERIOD=#{period}

DELETE FROM
CMWA_FUND_REVIEW WHERE FUNDID=#{funcode} AND REVIEW_STATUS != 'Y'

	AND PERIOD=#{period}

mapper.update:
UPDATE
CMWA_FUND_REVIEW SET
REVIEW_STATUS=#{status},REVIEW_BY=#{operatorId},UPDATETIMESTAMP=SYSDATE
WHERE FUNDID=#{fundid} 

	AND PERIOD=#{period}

mapper.select:
SELECT COUNT(*) FROM CMWA_FUND PRO WHERE 1=1

	AND PRO.FUNDID = #{sp.fundid}


	AND PRO.ADNAME = #{sp.dname}


	AND PRO.period = #{sp.period,jdbcType=NUMERIC}

select F.*,(case when eletype='110' then '小标题'    when eletype='120' then '大标题' when eletype='230' then 'PC图片' 
when eletype='240' then 'WX图片' end) as eletypeText  from CMWA_FUNDELEMENT F where  
fundid=#{fundid} and  eletype=#{eletype,jdbcType=INTEGER} and sortno=#{sortno,jdbcType=INTEGER}

SELECT FUNDID AS funcode , FUNDNM AS name FROM FUNDINFO WHERE FUNDID NOT IN (SELECT PMCO FROM PARAMETER WHERE PMST = 'SYSTEM' AND PMKY = 'UNFUNDID')
AND FUNDID =#{sp.fundid}
ORDER BY DISPLAYORDER ASC
